Optimal Solution (O(N) Time, O(1) Space):

Key Steps:
1. Find middle of the linked list using slow and fast pointers (Tortoise and Hare).
2. Reverse the second half of the linked list in-place.
3. Compare nodes of the first half and reversed second half one by one.
4. (Optional) Restore the original list structure.

C++ Code:
```cpp
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* reverseList(ListNode* head) {
    ListNode *prev = nullptr, *curr = head;
    while (curr) {
        ListNode* nextNode = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextNode;
    }
    return prev;
}

bool isPalindrome(ListNode* head) {
    if (!head || !head->next) return true;

    // 1. Find middle
    ListNode *slow = head, *fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }

    // 2. Reverse second half
    ListNode* secondHalf = reverseList(slow->next);

    // 3. Compare halves
    ListNode* p1 = head;
    ListNode* p2 = secondHalf;
    bool palindrome = true;
    while (p2) {
        if (p1->val != p2->val) {
            palindrome = false;
            break;
        }
        p1 = p1->next;
        p2 = p2->next;
    }

    return palindrome;
}
```

Optimal Solution (One-Pass Hash Map - O(N) Time, O(N) Space):

C++ Code:
```cpp
#include <vector>
#include <unordered_map>
using namespace std;

vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int, int> seen;
    for (int i = 0; i < nums.size(); i++) {
        int complement = target - nums[i];
        if (seen.find(complement) != seen.end()) {
            return {seen[complement], i};
        }
        seen[nums[i]] = i;
    }
    return {};
}
```
Time Complexity: O(N)
Space Complexity: O(N).

Optimal Solution (O(N) Time, O(N) Space):

Key Strategy:
Insert all numbers into an unordered hash set. Then for every number x in the set, check if (x + k) exists in the set. If it does, increment pair count.

C++ Code:
```cpp
#include <vector>
#include <unordered_set>
using namespace std;

int countPairsWithDiffK(const vector<int>& arr, int k) {
    unordered_set<int> numSet(arr.begin(), arr.end());
    int count = 0;
    for (int x : numSet) {
        if (numSet.find(x + k) != numSet.end()) {
            count++;
        }
    }
    return count;
}
```
Time Complexity: O(N) linear time.
Space Complexity: O(N) set storage.
